17	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
18	/// requires. Covers the I/O matrix (spec-2-1 + spec-2-2):
19	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
20	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
21	///   `false`, or throws `LocalAuthException`, including any OS lockout) ->
22	///   status stays [VaultStatus.locked], `Left(Failure.
23	///   malformedResponse(...))` — every one of those cases routes the caller
24	///   to [submitPin] next (spec-2-2), with no code-specific branch needed
25	///   here since the generic catches below already cover lockout.
26	/// - [submitPin], no PIN stored yet -> stores it, [VaultStatus.unlocked]
27	///   emitted, `Right(unit)`.
28	/// - [submitPin], stored PIN matches -> [VaultStatus.unlocked] emitted,
29	///   `Right(unit)`.
30	/// - [submitPin], stored PIN mismatch -> status stays locked, `Left(Failure.
31	///   malformedResponse(...))`, always retryable (no attempt cap).
32	///
33	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
34	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
35	/// reserved for password login) — every failure branch below maps only to
36	/// [Failure.malformedResponse]. The PIN is compared as a plain string
37	/// (Design Notes: `flutter_secure_storage` already encrypts at rest;
38	/// `package:crypto` isn't a pinned dependency) stored under [_pinStorageKey]
39	/// via the same [FlutterSecureStorage] instance
40	/// `SecureStorageAccessTokenProvider` uses for the access/refresh tokens.
41	class VaultRepositoryImpl
42	    with WidgetsBindingObserver
43	    implements VaultRepository {
44	  VaultRepositoryImpl({
45	    required LocalAuthentication localAuthentication,
46	    required FlutterSecureStorage secureStorage,
47	    DateTime Function() now = DateTime.now,
48	  }) : _localAuthentication = localAuthentication,
49	       _secureStorage = secureStorage,
50	       _now = now {
51	    // Story 2.3 — observes app-lifecycle transitions directly so idle
52	    // re-lock works with zero DI changes and zero new VaultRepository
53	    // methods. Removed in dispose() below.
54	    WidgetsBinding.instance.addObserver(this);
55	  }
56	
57	  static const _pinStorageKey = 'vault_pin';
58	
59	  final LocalAuthentication _localAuthentication;
60	  final FlutterSecureStorage _secureStorage;
61	  final DateTime Function() _now;
62	  final StreamController<VaultStatus> _statusController =
63	      StreamController<VaultStatus>.broadcast();
64	
65	  /// Set on `AppLifecycleState.paused`, read and cleared on
66	  /// `AppLifecycleState.resumed` (Boundaries: `inactive`/`hidden` are not
67	  /// "backgrounded" on their own — only this pair bounds iOS's actual
68	  /// background/foreground transition). `null` means either the app has
69	  /// never been backgrounded, or the last `paused`->`resumed` cycle already
70	  /// consumed it.
71	  DateTime? _backgroundedAt;
72	
73	  /// The last status emitted. Starts at [VaultStatus.locked] — not
74	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
75	  /// synchronously from construction, with no async warm-up step.
76	  VaultStatus _lastStatus = VaultStatus.locked;
77	
78	  @override
79	  VaultStatus get currentStatus => _lastStatus;
80	
81	  @override
82	  Stream<VaultStatus> get statusStream {
83	    // Same `Stream.multi` replay-to-late-listeners rationale as
84	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
85	    // after construction (but before any [authenticate] call) still
86	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
87	    // rather than nothing until the next emission.
88	    return Stream<VaultStatus>.multi((controller) {
89	      controller.add(_lastStatus);
90	      final subscription = _statusController.stream.listen(
91	        controller.add,
92	        onError: controller.addError,
93	        onDone: controller.close,
94	      );
95	      controller.onCancel = subscription.cancel;
96	    }, isBroadcast: true);
97	  }
98	
99	  void _emit(VaultStatus status) {
100	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
101	    // an in-flight `authenticate()` call — mirrors
102	    // `SessionRepositoryImpl._emit`'s own guard.
103	    if (_statusController.isClosed) {
104	      return;
105	    }
106	    _lastStatus = status;
107	    _statusController.add(status);
108	  }
109	
110	  @override
111	  void didChangeAppLifecycleState(AppLifecycleState state) {
112	    // Story 2.3's I/O & Edge-Case Matrix, exactly:
113	    // - `paused` -> record the backgrounded timestamp (only meaningful read
114	    //   on the next `resumed`).
115	    // - `resumed` with no prior `paused` recorded -> no-op (e.g. the very
116	    //   first lifecycle callback ever observed).
117	    // - `resumed` with elapsed time < 5 minutes -> no-op, `currentStatus`
118	    //   stays whatever it was.
119	    // - `resumed` with elapsed time >= 5 minutes AND `currentStatus` is
120	    //   currently `unlocked` -> emit `locked` exactly once; never
121	    //   redundantly if already `locked` (no duplicate emission).
122	    // `inactive`/`hidden` are intentionally ignored (Boundaries) — they
123	    // don't bound the real background/foreground transition on their own.
124	    if (state == AppLifecycleState.paused) {
125	      _backgroundedAt = _now();
126	      return;
127	    }
128	    if (state == AppLifecycleState.resumed) {
129	      final backgroundedAt = _backgroundedAt;
130	      _backgroundedAt = null;
131	      if (backgroundedAt == null) {
132	        return;
133	      }
134	      final elapsed = _now().difference(backgroundedAt);
135	      if (elapsed >= vaultIdleTimeout && _lastStatus == VaultStatus.unlocked) {
136	        _emit(VaultStatus.locked);
137	      }
138	    }
139	  }
140	
141	  @override
142	  Future<Either<Failure, Unit>> authenticate() async {
143	    try {
144	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
145	      // OS's own device-passcode UI satisfy this call, which would bypass
146	      // Cerne's own PIN screen (Story 2.2) entirely.
147	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
148	      // (e.g. an incoming call) retries on foreground instead of failing
149	      // outright.
150	      final success = await _localAuthentication.authenticate(
151	        localizedReason: 'Autentique-se para acessar o Cerne',
152	        biometricOnly: true,
153	        persistAcrossBackgrounding: true,
154	      );
155	      if (success) {
156	        _emit(VaultStatus.unlocked);
157	        return right(unit);
158	      }
159	      // A `false` result (declined/unavailable, no exception) — status
160	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
161	      // for password login).
162	      return left(
163	        const Failure.malformedResponse(
164	          message: 'Biometric authentication was not successful',
165	        ),
166	      );
167	    } on LocalAuthException catch (error) {
168	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
169	      // etc. (RNF09: never let a platform exception escape unmapped).
170	      return left(Failure.malformedResponse(message: error.toString()));
171	    } catch (error) {
172	      // Any other thrown platform exception (e.g. the plugin's channel
173	      // itself failing) must never escape unmapped either (RNF09) — fail
174	      // closed, same as the documented `LocalAuthException` branch above,
175	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
176	      // `catch`.
177	      return left(Failure.malformedResponse(message: error.toString()));
178	    }
179	  }
