      // has no attempt cap — always retryable"); never `Failure.authInvalid`
      // (reserved for password login), same rationale as `authenticate()`.
      return left(
        const Failure.malformedResponse(
          message: 'PIN did not match the stored PIN',
        ),
      );
    } catch (error) {
